-- ======================================================================
-- ORIANA - SEED DATA MIGRACIÓN DESDE EXCEL
-- ======================================================================

-- 1. USUARIOS
ON CONFLICT (usuario) DO UPDATE SET
  clave = EXCLUDED.clave, nombre_apellido = EXCLUDED.nombre_apellido, rol = EXCLUDED.rol, turno = EXCLUDED.turno, id_user = EXCLUDED.id_user, cedula = EXCLUDED.cedula;

-- 2. REGLAS_ACCESO
ON CONFLICT (perfil) DO UPDATE SET modos_permitidos = EXCLUDED.modos_permitidos;

-- 3. AREAS_TRABAJO
ON CONFLICT (id_area) DO UPDATE SET nombre_area = EXCLUDED.nombre_area;

-- 4. CONFIGURACION
ON CONFLICT (modo) DO UPDATE SET campanas = EXCLUDED.campanas;



-- 6. LOGS_AUDITORIA

